    // 添加投票
    if (res.pollData) {
        let poll = `📃 投票(✅${res.pollData.total}已投)：\n${res.pollData.question}\n`
        res.pollData.choices.forEach(choice => {
            poll += `选项${choice.id}：${choice.text}(✅${choice.count})\n`
        })
        content += "\n" + "——————————\n".repeat(2) + poll
