    })
    return text.trim()
}

function blockShowFactory() {
    let keys = Object.keys(wordsType)
    let key = getFromCacheObject("wordsType")

    // 切换屏蔽列表
    let index = keys.indexOf(key) + 1
    if (index === keys.length) index = 0
    key = keys[index]
    putInCacheObject("wordsType", key)

