    else if (word) {
        sleepToast(`⭕️ 删除屏蔽\n${wordsType[method]}\n\n⚠️ 输入【用户ID】可屏蔽该作者`)
    }
    putInCacheMap(`blockAuthorMap`, blockAuthors)
}

