function getPixivUid() {
    let uid = getFromCache("pixiv:uid")
    if (!uid || String(uid) === "null") {
        let html = java.webView(null, "https://www.pixiv.net/", null)
        try {
            uid = html.match(/user_id:'(\d+)'/)[1]
        } catch (e) {
            uid = null
        }
        putInCache("pixiv:uid", String(uid))
    }
}

