            pixivCsrfToken = null
            cache.delete("pixivCsrfToken")  // 与登录设备有关，无法存储 nul
            // sleepToast("⚠️ 未登录账号(pixivCsrfToken)")
        }
        java.log(`pixivCsrfToken:\n${pixivCsrfToken}`)
    }
    return pixivCsrfToken
