function login() {
    var baseUrl = 'https://taijiwang.top';
    java.startBrowserAwait(baseUrl + '/user', '登录');
    var ck = String(cookie.getCookie(baseUrl) || '');
    if (ck && ck.indexOf('admin_session') >= 0) {
        java.toast('\n\n✅ 登录成功');
    } else {
        java.toast('\n\n⚠️ 未检测到登录状态，请确保在浏览器中完成登录后再关闭');
    }
}

function checkLogin() {
    var baseUrl = 'https://taijiwang.top';
    var ck = String(cookie.getCookie(baseUrl) || '');
    if (ck && ck.indexOf('admin_session') >= 0) {
        try {
            var a = JSON.parse(java.ajax(baseUrl + '/user/api/dashboard'));
            var tip = '\n✅ 当前已登录\n' + a.user.nickname + '\n总次数：' + a.quota.daily_limit + '\n已使用：' + a.quota.daily_used + '\n设备使用：' + a.quota.active_sessions + '/' + a.quota.max_sessions;
            java.toast(tip);
        } catch(e) {
            java.toast('\n\n✅ 当前已登录（获取详情失败）');
        }
    } else {
        java.toast('\n\n❌ 当前未登录');
    }
}

function logout() {
    var baseUrl = 'https://taijiwang.top';
    cookie.removeCookie(baseUrl);
    java.toast('\n\n✅ 已退出登录');
}

function xflogin() {
    java.startBrowserAwait('https://m.qidian.com', '起点');
}

